import { edit_orders } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    cancelOrderDialig: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      cancelReason: ""
    };
  },
  watch: {
    cancelOrderDialig: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async validate_delete() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.delete_Entity();
      }
    },
    async delete_Entity() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_orders, {
          input: {
            order_id: this.rowInfo.order_id,
            order_delevery_status: "CANCELLED",
            cancel_reason: this.cancelReason
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_orders);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
